package app.nullvault;

import android.app.*;
import android.os.*;
import android.content.*;
import android.content.ClipboardManager;
import android.net.Uri;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import android.text.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
 private JSONArray entries;
 private byte[] key,salt;
 private File vault;
 private LinearLayout body,root;
 private final Handler main=new Handler(Looper.getMainLooper());
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private int generation=0,selected=-1;
 private boolean active=false,busy=false;
 private Uri pendingImport;
 private AlertDialog dialog;
 private String copied=null;
 private final int BG=0xff10141d,CARD=0xff1c2330,INK=0xffedf1fa,MUTED=0xffaebbd0,BLUE=0xff8eb6ff;
 private final Runnable tick=new Runnable(){public void run(){if(active&&entries!=null&&selected>=0&&otpText!=null){updateOtp();main.postDelayed(this,1000);}}};
 private TextView otpText,countdown;
 private boolean revealOtp=false;
 private int dp(int n){return (int)(getResources().getDisplayMetrics().density*n);}
 private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));return d;}
 private TextView label(LinearLayout parent,String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(dp(6),dp(9),dp(6),dp(9));parent.addView(t);return t;}
 private TextView text(String value,int size){return label(body,value,size,INK);}
 private void page(String title,boolean tabs){main.removeCallbacks(tick);selected=-1;otpText=null;countdown=null;revealOtp=false;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(dp(16),dp(12),dp(16),dp(12));root.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(dp(16)+in.getSystemWindowInsetLeft(),dp(12)+in.getSystemWindowInsetTop(),dp(16)+in.getSystemWindowInsetRight(),dp(12)+in.getSystemWindowInsetBottom());return in;});setContentView(root);root.requestApplyInsets();TextView h=label(root,title,28,INK);h.setTypeface(null,Typeface.BOLD);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(tabs){LinearLayout nav=new LinearLayout(this);root.addView(nav);navButton(nav,"Vault",()->showVault(""));navButton(nav,"Settings",this::settings);navButton(nav,"Lock",this::lock);}}
 private void navButton(LinearLayout row,String value,Runnable action){Button b=new Button(this);b.setText(value);b.setTextColor(BLUE);b.setBackgroundColor(BG);row.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));b.setOnClickListener(v->action.run());}
 private Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextColor(BG);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(BLUE));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.setMargins(0,dp(6),0,dp(6));body.addView(b,lp);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 private EditText field(String name,String value,boolean secret){label(body,name,13,MUTED);EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setTextSize(16);e.setPadding(dp(16),dp(12),dp(16),dp(12));e.setBackground(shape(CARD));e.setInputType(secret?129:1);e.setText(value);e.setSaveEnabled(false);body.addView(e,new LinearLayout.LayoutParams(-1,dp(52)));return e;}
 private void message(String title,String value){if(!active)return;if(dialog!=null)dialog.dismiss();dialog=new AlertDialog.Builder(this).setTitle(title).setMessage(value).setPositiveButton("OK",null).create();dialog.getWindow();dialog.show();dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}
 private void hideKeyboard(){View v=getCurrentFocus();if(v!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);}
 public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);vault=new File(getFilesDir(),"vault.json");active=true;unlock();}
 private static void wipe(byte[] b){if(b!=null)Arrays.fill(b,(byte)0);}
 private void unlock(){page("NullVault",false);text("Your vault. Your control.",20);text("Preview 0.2 · Test data only",14);boolean exists=vault.exists();text(exists?"Unlock vault":"Create a local vault",22);EditText pass=field("Master password","",true),confirm=exists?null:field("Confirm password","",true);TextView status=text("",14);Button go=button(exists?"Unlock":"Create vault",()->{
  char[] password=pass.getText().toString().toCharArray();if(!exists&&(password.length<12||!pass.getText().toString().equals(confirm.getText().toString()))){Arrays.fill(password,'\0');message("Check password","Use at least 12 characters and matching passwords.");return;}pass.setText("");if(confirm!=null)confirm.setText("");hideKeyboard();busy=true;status.setText("Unlocking securely…");int token=generation;
  worker.execute(()->{byte[] localKey=null;try{byte[] localSalt;JSONArray localEntries;if(exists){JSONObject envelope=new JSONObject(new String(Files.readAllBytes(vault.toPath()),StandardCharsets.UTF_8));localSalt=VaultEngine.salt(envelope);localKey=VaultEngine.derive(password,localSalt);localEntries=VaultEngine.open(envelope,localKey);}else{if(vault.exists())throw new Exception("Vault already created; unlock it instead");localSalt=VaultEngine.random(16);localKey=VaultEngine.derive(password,localSalt);localEntries=new JSONArray();writeVault(localEntries,localKey,localSalt);}byte[] finishedKey=localKey;main.post(()->{if(!active||token!=generation){wipe(finishedKey);return;}key=finishedKey;salt=localSalt;entries=localEntries;busy=false;showVault("");if(pendingImport!=null){Uri next=pendingImport;pendingImport=null;readImport(next);}});}catch(Exception ex){wipe(localKey);main.post(()->{if(active&&token==generation){busy=false;unlock();message("Could not unlock","Check your password. Damaged or unsupported vault files can also cause this error.");}});}finally{Arrays.fill(password,'\0');}});
 });text("Encrypted on this device. No subscription or network connection required.",14);}
 private void writeVault(JSONArray items,byte[] k,byte[] s)throws Exception{byte[] data=VaultEngine.seal(items,k,s).toString().getBytes(StandardCharsets.UTF_8);File temp=new File(getFilesDir(),"vault.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(data);out.getFD().sync();}Files.move(temp.toPath(),vault.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 private void save(JSONArray replacement,Runnable done){if(key==null||busy)return;busy=true;byte[] k=key.clone(),s=salt.clone();int token=generation;worker.execute(()->{try{writeVault(replacement,k,s);main.post(()->{if(active&&token==generation){entries=replacement;busy=false;done.run();}});}catch(Exception ex){main.post(()->{if(active&&token==generation){busy=false;message("Save failed","Your previous vault was retained. Please try again.");}});}finally{wipe(k);wipe(s);}});}
 private void showVault(String query){if(entries==null)return;page("My vault",true);EditText search=field("Search vault",query,false);LinearLayout list=new LinearLayout(this);list.setOrientation(1);body.addView(list);renderList(list,query);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){renderList(list,s.toString());}public void afterTextChanged(Editable e){}});button("+ Add item",()->edit(-1));}
 private void renderList(LinearLayout list,String query){list.removeAllViews();String q=query.toLowerCase(Locale.ROOT);int count=0;for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);if(e==null)continue;if(!(e.optString("title")+" "+e.optString("username")).toLowerCase(Locale.ROOT).contains(q))continue;final int index=i;LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(dp(12),dp(6),dp(12),dp(6));row.setBackground(shape(CARD));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));list.addView(row,lp);label(row,e.optString("title"),19,INK).setTypeface(null,Typeface.BOLD);label(row,e.optString("username").isEmpty()?"Secure item":e.optString("username"),14,MUTED);label(row,e.optString("totp").isEmpty()?"Login / note  ›":"Authenticator  ›",12,BLUE);row.setContentDescription(e.optString("title")+", "+e.optString("username")+", open item");row.setFocusable(true);row.setOnClickListener(v->details(index));count++;}if(count==0)label(list,entries.length()==0?"Your vault is empty. Add an item or import a backup in Settings.":"No matching items",16,MUTED);}
 private void details(int index){if(entries==null)return;JSONObject e=entries.optJSONObject(index);page(e.optString("title"),true);selected=index;label(body,"USERNAME",12,BLUE);text(e.optString("username","—"),18);if(!e.optString("username").isEmpty())button("Copy username",()->copy(e.optString("username")));if(!e.optString("password").isEmpty()){label(body,"PASSWORD",12,BLUE);TextView password=text("••••••••••••",20);button("Show / hide password",()->password.setText(password.getText().toString().equals("••••••••••••")?e.optString("password"):"••••••••••••"));button("Copy password",()->copy(e.optString("password")));}
  if(!e.optString("totp").isEmpty()){label(body,"VERIFICATION CODE",12,BLUE);otpText=text("••••••",32);otpText.setTypeface(Typeface.MONOSPACE);countdown=text("",14);button("Show / hide verification code",()->{revealOtp=!revealOtp;updateOtp();});button("Copy verification code",()->{try{copy(VaultEngine.code(e,System.currentTimeMillis()/1000));}catch(Exception ex){message("Code unavailable",ex.getMessage());}});tick.run();}
  if(!e.optString("url").isEmpty()){label(body,"WEBSITE",12,BLUE);text(e.optString("url"),16);}if(!e.optString("notes").isEmpty()){label(body,"NOTES",12,BLUE);text(e.optString("notes"),16);}button("Edit item",()->edit(index));button("Back to vault",()->showVault(""));}
 private void updateOtp(){if(entries==null||selected<0||otpText==null)return;JSONObject e=entries.optJSONObject(selected);try{otpText.setText(revealOtp?VaultEngine.code(e,System.currentTimeMillis()/1000):"••••••");int p=e.optInt("period",30);countdown.setText((p-System.currentTimeMillis()/1000%p)+" seconds remaining");}catch(Exception ex){otpText.setText("Unavailable");}}
 private void edit(int index){JSONObject old=index<0?new JSONObject():entries.optJSONObject(index);page(index<0?"New item":"Edit item",true);EditText name=field("Name",old.optString("title"),false),user=field("Username",old.optString("username"),false),pass=field("Password",old.optString("password"),true),otp=field("Authenticator secret or otpauth link",old.optString("totp"),true),url=field("Website",old.optString("url"),false),notes=field("Notes",old.optString("notes"),false);notes.setSingleLine(false);button("Save item",()->{try{JSONObject e=new JSONObject(old.toString());e.put("title",name.getText().toString().trim());e.put("username",user.getText().toString());e.put("password",pass.getText().toString());e.put("url",url.getText().toString());e.put("notes",notes.getText().toString());String secret=otp.getText().toString().trim();if(secret.startsWith("otpauth://")){JSONObject parsed=VaultEngine.fromUri(secret);for(String k:Arrays.asList("totp","algorithm","digits","period"))e.put(k,parsed.get(k));}else e.put("totp",VaultEngine.clean(secret));VaultEngine.validate(e);JSONArray updated=new JSONArray(entries.toString());if(index<0){e.put("id",UUID.randomUUID().toString());updated.put(e);}else updated.put(index,e);hideKeyboard();save(updated,()->showVault(""));}catch(Exception ex){message("Check entry",ex.getMessage());}});button("Cancel",()->showVault(""));}
 private void copy(String value){ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);ClipData clip=ClipData.newPlainText("NullVault",value);if(Build.VERSION.SDK_INT>=33){PersistableBundle extras=new PersistableBundle();extras.putBoolean("android.content.extra.IS_SENSITIVE",true);clip.getDescription().setExtras(extras);}clipboard.setPrimaryClip(clip);copied=value;main.postDelayed(this::clearClipboard,30000);Toast.makeText(this,"Copied · clears in 30 seconds",Toast.LENGTH_SHORT).show();}
 private void clearClipboard(){if(copied==null)return;ClipboardManager c=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(c.hasPrimaryClip()&&c.getPrimaryClip()!=null&&copied.contentEquals(c.getPrimaryClip().getItemAt(0).coerceToText(this))){if(Build.VERSION.SDK_INT>=28)c.clearPrimaryClip();else c.setPrimaryClip(ClipData.newPlainText("",""));}copied=null;}
 private void settings(){page("Settings",true);text("Data & backups",22);text("Import Aegis unencrypted JSON, Bitwarden unencrypted vault JSON (logins and notes), otpauth text, or NullVault encrypted backups. Unsupported types stop the import; entries are never silently discarded.",15);button("Import from file",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);});button("Paste otpauth link",()->{page("Import authenticator",true);EditText uri=field("otpauth://totp/…","",true);button("Preview import",()->{try{preview(VaultEngine.parseImport(uri.getText().toString()));}catch(Exception ex){message("Import failed",ex.getMessage());}});});button("Export encrypted backup",()->{messageExport();});text("Backups use your current master password. Keep that password; it is required to restore on another device.",14);text("Nextcloud, encrypted Aegis/Bitwarden imports, camera QR import, attachments, autofill and FIDO are not implemented yet.",14);text("0.2.0 Preview · Local only",14);}
 private void messageExport(){dialog=new AlertDialog.Builder(this).setTitle("Export encrypted backup").setMessage("All entries will be encrypted with your current master password. You choose the destination in Android’s file picker.").setPositiveButton("Choose destination",(d,w)->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"NullVault-backup-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmm",Locale.ROOT).format(new Date())+".json");startActivityForResult(i,11);}).setNegativeButton("Cancel",null).create();dialog.show();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==10){pendingImport=uri;unlock();}else if(request==11){worker.execute(()->{try(InputStream in=new FileInputStream(vault);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);out.flush();main.post(()->message("Backup exported","Encrypted backup saved. Restore it using this vault’s master password."));}catch(Exception ex){main.post(()->message("Export failed","The backup could not be saved. Try another destination."));}});}}
 private void readImport(Uri uri){int token=generation;worker.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>10*1024*1024)throw new Exception("Import exceeds the 10 MB preview limit");out.write(buffer,0,n);}String source=out.toString("UTF-8");main.post(()->{if(active&&token==generation&&entries!=null)decodeImport(source);});}catch(Exception ex){main.post(()->{if(active&&token==generation)message("Import failed",Objects.toString(ex.getMessage(),"Could not read file"));});}});}
 private void decodeImport(String source){try{JSONObject envelope=source.trim().startsWith("{")?new JSONObject(source):null;if(envelope!=null&&envelope.has("iterations")&&envelope.has("data")&&envelope.has("salt")){EditText password=new EditText(this);password.setInputType(129);password.setHint("Backup master password");password.setSaveEnabled(false);dialog=new AlertDialog.Builder(this).setTitle("Unlock NullVault backup").setView(password).setPositiveButton("Unlock",(d,w)->{char[] p=password.getText().toString().toCharArray();password.setText("");int token=generation;busy=true;worker.execute(()->{byte[] k=null;try{k=VaultEngine.derive(p,VaultEngine.salt(envelope));JSONArray incoming=VaultEngine.open(envelope,k);for(int i=0;i<incoming.length();i++)VaultEngine.validate(incoming.getJSONObject(i));main.post(()->{if(active&&token==generation){busy=false;preview(incoming);}});}catch(Exception ex){main.post(()->{if(active&&token==generation){busy=false;message("Backup not unlocked","Incorrect password or invalid backup. No entries were changed.");}});}finally{wipe(k);Arrays.fill(p,'\0');}});}).setNegativeButton("Cancel",null).create();dialog.show();dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}else{int token=generation;busy=true;worker.execute(()->{try{JSONArray incoming=VaultEngine.parseImport(source);main.post(()->{if(active&&token==generation){busy=false;preview(incoming);}});}catch(Exception ex){main.post(()->{if(active&&token==generation){busy=false;message("Import failed",ex.getMessage());}});}});}}catch(Exception ex){message("Import failed",ex.getMessage());}}
 private void preview(JSONArray incoming){try{JSONArray merged=VaultEngine.merge(entries,incoming);int added=merged.length()-entries.length();dialog=new AlertDialog.Builder(this).setTitle("Import preview").setMessage(incoming.length()+" entries read\n"+added+" new entries\n"+(incoming.length()-added)+" duplicates skipped\n\nExisting entries will be retained.").setPositiveButton("Import",(d,w)->save(merged,()->{showVault("");message("Import complete",added+" entries added.");})).setNegativeButton("Cancel",null).create();dialog.show();}catch(Exception ex){message("Import failed",ex.getMessage());}}
 private void lock(){generation++;busy=false;main.removeCallbacks(tick);wipe(key);key=null;salt=null;entries=null;if(dialog!=null){dialog.dismiss();dialog=null;}if(active)clearClipboard();unlock();}
 protected void onStart(){super.onStart();active=true;}
 protected void onStop(){active=false;lock();super.onStop();}
 protected void onDestroy(){clearClipboard();generation++;main.removeCallbacksAndMessages(null);worker.shutdown();super.onDestroy();}
 public void onBackPressed(){if(entries!=null)showVault("");else super.onBackPressed();}
}
